const TOOLS = [
  {
    name: 'customer_lookup',
    description: 'Look up a customer by their unique customer_id and return their details as text.',
    inputSchema: {
      type: 'object',
      properties: {
        customer_id: {
          type: 'string',
          description: 'The unique identifier of the customer to look up.'
        }
      },
      required: ['customer_id'],
      additionalProperties: false
    }
  }
];

export async function listTools() {
  return TOOLS;
}

export async function callTool(name, args) {
  if (name !== 'customer_lookup') {
    throw new Error(`Unknown tool: ${name}`);
  }

  if (!args || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Invalid arguments: expected an object');
  }

  if (args.customer_id === undefined) {
    throw new Error("Missing required argument: 'customer_id'");
  }

  if (typeof args.customer_id !== 'string') {
    throw new Error("Invalid argument: 'customer_id' must be a string");
  }

  const customer = customers[args.customer_id];
  if (!customer) {
    throw new Error(`Unknown customer_id: ${args.customer_id}`);
  }

  const text = `customer_id: ${args.customer_id}\nname: ${customer.name}\ntier: ${customer.tier}`;
  return {
    content: [{ type: 'text', text }]
  };
}
